-- c025-v001: Phḗstos pues habiendo-entrado en–la provincia después-de tres días subió a Hierosólyma desde Kaisáreia
-- c025-v002: informaron * a–él los sumos-sacerdotes y los principales de–los judíos contra – Paûlos y rogaban a–él
-- c025-v003: pidiendo favor contra él que mandara-llamar a–él a Hierousalḗm emboscada haciendo matar a–él por el camino
-- c025-v004: el * pues Phḗstos respondió ser-custodiado – Paûlos en Kaisáreia él-mismo * estar-a-punto en breve de–partir
-- c025-v005: Los pues entre vosotros dice capaces habiendo-descendido-juntos si algo hay en el hombre malo acúsenlo a–él
-- c025-v006: Habiendo-permanecido * entre ellos días no más-de ocho o diez habiendo-descendido a Kaisáreia al día-siguiente habiéndose-sentado sobre el tribunal ordenó a– Paûlos ser-traído
-- c025-v007: habiendo-llegado * él rodearon a–él los desde Hierosólyma habiendo-descendido judíos muchas y graves acusaciones trayendo las-cuales no podían probar
-- c025-v008: – Paûlos defendiéndose que Ni contra la ley de–los judíos ni contra el templo ni contra Káisar en–nada pequé
-- c025-v009: el Phḗstos * queriendo a–los judíos favor conceder habiendo-respondido a– Paûlos dijo Quieres a Hierosólyma habiendo-subido allí acerca-de estas-cosas ser-juzgado ante mí
-- c025-v010: dijo * – Paûlos Estando-de-pie ante el tribunal de–Káisar estoy donde me es-necesario ser-juzgado A–judíos en–nada agravé como también tú mejor sabes
-- c025-v011: si * pues obro-injustamente y digno de–muerte he-hecho algo no rehuso – morir si * nada hay de-lo-cual estos me-acusan a–mí nadie me puede a–ellos entregar A–Káisar apelo
-- c025-v012: entonces el Phḗstos habiendo-conferido con el consejo respondió A–Káisar has-apelado a Káisar irás
-- c025-v013: De–días * habiendo-pasado algunos Agríppas el rey y Berníkē llegaron a Kaisáreia habiendo-saludado a– Phḗstos
-- c025-v014: como * más días permanecían allí el Phḗstos al rey expuso las-cosas respecto-a – Paûlos diciendo Hombre cierto hay dejado por Phḗlix prisionero
-- c025-v015: acerca-de quien habiendo-llegado yo a Hierosólyma informaron los sumos-sacerdotes y los ancianos de–los judíos pidiendo contra él condena
-- c025-v016: a quienes respondí que no es costumbre de–romanos entregar a–algún hombre antes que el acusado cara-a cara tenga a–los acusadores lugar * de–defensa reciba acerca-de el cargo
-- c025-v017: habiendo-venido-juntos pues ellos aquí demora ninguna habiendo-hecho al siguiente habiéndome-sentado sobre el tribunal ordené ser-traído al hombre
-- c025-v018: acerca-de quien habiéndose-puesto-de-pie los acusadores ninguna causa traían de-las-cuales yo suponía malas
-- c025-v019: cuestiones * ciertas acerca-de la propia religión tenían contra él y acerca-de cierto Iēsoûs habiendo-muerto a-quien afirmaba – Paûlos vivir
-- c025-v020: estando-perplejo * yo la acerca-de estas-cosas investigación decía si quería ir a Hierosólyma y–allí ser-juzgado acerca-de estas-cosas
-- c025-v021: – * Paûlos habiendo-apelado ser-guardado él para la del Sebastós decisión ordené ser-custodiado a–él hasta que lo-envíe a–él ante Káisar
-- c025-v022: Agríppas * a – Phḗstos Quería también yo-mismo del hombre oír Mañana dice oirás de–él
-- c025-v023: A–el pues día-siguiente habiendo-venido – Agríppas y – Berníkē con mucha pompa y habiendo-entrado a la sala-de-audiencias junto-con * tribunos y hombres los de prominencia de–la ciudad y habiendo-ordenado – Phḗstos fue-traído – Paûlos
-- c025-v024: y dice – Phḗstos Agríppas rey y todos los presentes-con nosotros varones ved a–este acerca-de quien toda la multitud de–los judíos me-peticionaron a–mí en * Hierosólyma y aquí clamando no deber a–él vivir más
-- c025-v025: yo * comprendí nada digno él de–muerte haber-hecho él-mismo * este habiendo-apelado al Sebastós decidí enviar
-- c025-v026: acerca-de quien algo-seguro algo escribir al señor no tengo por-lo-cual lo-traje a–él ante vosotros y especialmente ante ti rey Agríppas para-que la investigación habiendo-sucedido tenga algo que–escribir
